export const meta = {
  name: 'esp32p4-docs-review',
  description: 'Review ESP32-P4 documentation and create development plan',
  phases: [
    { title: 'Review', detail: 'Analyze all documentation' },
    { title: 'Plan', detail: 'Create development roadmap' },
  ],
};

// Phase 1: Review all documentation
phase('Review');

const docs = [
  'esp32p4-hardware-reference.md',
  'esp-idf-development-guide.md',
  'openvela-porting-guide.md',
  'esp32p4-examples-guide.md'
];

const reviews = await pipeline(
  docs,
  doc => agent(`Review /home/geo/openvela/docs/${doc} and summarize key points for ESP32-P4 development with openvela`, {
    label: `review:${doc}`,
    phase: 'Review'
  })
);

// Phase 2: Create development plan
phase('Plan');

const plan = await agent(
  `Based on the following documentation reviews, create a comprehensive development plan for ESP32-P4 adaptation with openvela:

${reviews.join('\n\n---\n\n')}

Include:
1. Priority tasks for hardware adaptation
2. Driver development roadmap
3. Build system integration steps
4. Testing and validation plan
5. Timeline estimation

Save the plan to /home/geo/openvela/docs/esp32p4-development-plan.md`,
  { label: 'create-plan', phase: 'Plan' }
);

return { reviews, plan };
